    num_dict = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    if not numbers:
        return ''
    nums = numbers.split()
    if not all(num in num_dict for num in nums):
        return ''
    nums = sorted([num_dict[num] for num in nums])
    return ' '.join([list(num_dict.keys())[list(num_dict.values()).index(num)] for num in nums])

