def find_zero(xs):
    def derivative(xs, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs)])

    def newton_raphson(xs, x0, tol=1e-5, max_iter=100):
        x = x0
        for _ in range(max_iter):
            f_x = poly(xs, x)
            f_x_prime = derivative(xs, x)
            if abs(f_x) < tol:
                return x
            x = x - f_x / f_x_prime
        return x

    x0 = -xs[-1] / xs[-2]
    return newton_raphson(xs, x0)

